javas.java:

int def eduRank(str:education) {
    if (education == "PHD") {
        return 4;
    } else if (education == "MASTER") {
        return 3;
    } else if (education == "BACHELOR") {
        return 2;
    } else {
        return 1;
    }
}


boolean def educationPass(int:actualRank, int:requiredRank) {
    if (actualRank >= requiredRank) {
        return true;
    } else {
        return false;
    }
}


boolean def experiencePass(int:yearsExperience, int:requiredYears) {
    if (yearsExperience >= requiredYears) {
        return true;
    } else {
        return false;
    }
}


boolean def skillPass(int:skillMatchCount, int:requiredSkillCount) {
    if (requiredSkillCount <= 0) {
        return true;
    } else if (skillMatchCount * 100 >= requiredSkillCount * 80) {
        return true;
    } else {
        return false;
    }
}


boolean def salaryPass(double:expectedSalary, double:salaryMin, double:salaryMax) {
    if (expectedSalary <= salaryMax && expectedSalary >= salaryMin * 0.8) {
        return true;
    } else {
        return false;
    }
}


boolean def locationPass(str:currentCity, str:jobCity, boolean:willingToRelocate) {
    if (currentCity == jobCity || willingToRelocate) {
        return true;
    } else {
        return false;
    }
}


boolean def hardReject(int:jobHoppingCount, int:gapMonths) {
    if (jobHoppingCount >= 4 || gapMonths >= 24) {
        return true;
    } else {
        return false;
    }
}


int def scoreEducation(int:actualRank, int:requiredRank, str:schoolTier) {
    int score = 0;
    if (actualRank - requiredRank >= 2) {
        score = 20;
    } else if (actualRank - requiredRank == 1) {
        score = 15;
    } else if (actualRank == requiredRank) {
        score = 10;
    }
    if (schoolTier == "985") {
        score = score + 5;
    } else if (schoolTier == "211") {
        score = score + 3;
    }
    return score;
}


int def scoreExperience(int:yearsExperience, int:requiredYears) {
    int extra = yearsExperience - requiredYears;
    if (extra >= 5) {
        return 25;
    } else if (extra >= 2) {
        return 20;
    } else if (extra >= 0) {
        return 12;
    } else {
        return 0;
    }
}


int def scoreSkills(int:skillMatchCount, int:requiredSkillCount) {
    if (requiredSkillCount <= 0) {
        return 20;
    } else if (skillMatchCount >= requiredSkillCount) {
        return 20;
    } else if (skillMatchCount * 100 >= requiredSkillCount * 80) {
        return 14;
    } else if (skillMatchCount * 100 >= requiredSkillCount * 60) {
        return 8;
    } else {
        return 0;
    }
}


int def scoreStability(int:jobHoppingCount, int:gapMonths) {
    int score = 0;
    if (jobHoppingCount == 0) {
        score = 15;
    } else if (jobHoppingCount == 1) {
        score = 10;
    } else if (jobHoppingCount == 2) {
        score = 5;
    }
    if (gapMonths <= 3) {
        score = score + 5;
    }
    return score;
}


int def scoreBonus(boolean:certified, str:englishLevel) {
    int score = 0;
    if (certified) {
        score = score + 5;
    }
    if (englishLevel == "CET6") {
        score = score + 5;
    } else if (englishLevel == "CET4") {
        score = score + 3;
    }
    return score;
}


str def screeningResult(int:totalScore, boolean:hardCheckPass, boolean:hardReject) {
    if (hardReject) {
        return "REJECT";
    } else if (hardCheckPass == false) {
        return "REJECT";
    } else if (totalScore >= 75) {
        return "INTERVIEW";
    } else if (totalScore >= 55) {
        return "RESERVE";
    } else {
        return "REJECT";
    }
}


str def recommendLevel(int:totalScore) {
    if (totalScore >= 85) {
        return "STRONG";
    } else if (totalScore >= 75) {
        return "NORMAL";
    } else if (totalScore >= 55) {
        return "RESERVE";
    } else {
        return "NONE";
    }
}
